<include file="Public:header"/>	<div class="mainbox">		<table class="search_table" width="100%">			<tr>				<td style="width:60%;">										订单列表										<!-- <a  href="javascript:void(0)" onclick="doBill()" class="button  " style=" color: #fff;background: #1890FF;border: solid 1px #1890FF;">确认对账</a>					<a  href="javascript:void(0)" onclick="exports()" class="button" style="margin-left: 10px;">导出</a> -->															</td>			</tr>		</table>					<div class="table-list">				<table width="100%" cellspacing="0">					<colgroup><col> <col><col><col width="240" align="center"> </colgroup>					<thead>						<tr>                            <!-- <th><input type="checkbox" id='checkall'/>{pigcms{:L_("全选")}</th> -->							<th>店铺名称</th>							<th>订单号</th>							<th>订单类型</th>							<th>订单金额</th>							<!-- <th>在线支付金额</th>							<th>平台支付金额</th>							<th>商家会员卡余额支付金额</th>							<th>平台优惠券抵现</th>							<th>商家优惠券抵现</th>							<th>积分抵现</th>							<th>店员收取金额</th> -->							<th>下单时间</th>							<!-- <th>支付时间</th> -->							<!-- <th>订单状态</th> -->							<!-- <th>对账状态</th> -->						</tr>					</thead>					<tbody>						<if condition="is_array($order_list)">							<volist name="order_list" id="vo">								<tr>									<!-- <td>										<if condition="$vo['is_bill'] eq 0">											<input type="checkbox" name="order_ids" value="{pigcms{$vo['id']}">										</if>									</td> -->									<td>{pigcms{$vo.store_name|default="--"}</td>									<td>{pigcms{$vo.real_orderid}</td>									<td>{pigcms{$vo.business_name}</td>									<td>{pigcms{$vo.price}</td>									<!-- <td>{pigcms{$vo.balance_pay}</td>									<td>{pigcms{$vo.merchant_balance}</td>									<td>{pigcms{$vo.coupon_price}</td>									<td>{pigcms{$vo.card_price}</td>									<td>{pigcms{$vo.score_deducte}</td>									<td>{pigcms{$vo.cash}</td> -->									<td>{pigcms{$vo.create_time|date='Y-m-d H:i:s',###}</td>									<!-- <td>										<if condition="$vo['pay_time']">											{pigcms{$vo.pay_time|date='Y-m-d H:i:s',###}										<else/>											--										</if>									</td> -->									<!-- <td>										<if condition="$vo['paid'] eq 0">											<span style="color:red;">未支付</span>										<elseif condition="$vo['system_status'] eq 4"/>											<span style="color:red">已退款</span>										<else/>											<span style="color:#1890ff">已支付</span>										</if>									</td> -->									<!-- <td>										<if condition="$vo['is_bill']">											<span style="color:#1890ff;">已对账</span>										<else/>											<span style="color:red">未对账</span>										</if>									</td> -->								</tr>							</volist>							<tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr>						<else/>							<tr><td class="textcenter red" colspan="5">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>		</div>	<script type="text/javascript">		var export_url = "{pigcms{:U('Merchant_bill/export',$_GET)}"		var check_num=0;	    var order_id_list = '';	    var count = $('input[name="order_ids"]').length;	    var order_arr = [];	    // "单选")}	    $('input[name="order_ids"]').click(function(){	        var order_id = $(this).val();	        if($(this).is(":checked")){	            order_arr.push(order_id);	            check_num++;	        }else{	            order_arr.splice($.inArray(order_id, order_arr), 1);	            check_num--;	        }	        if(check_num<count){	            $("input#checkall").prop('checked',false);	        }else{	            $("input#checkall").prop('checked',true);	        }	        order_id_list = order_arr.join(',');	        console.log('order_id_list----', order_id_list);	       	    });	    /*{pigcms{:L_("批量选择")}*/	    $(document).on('click','#checkall',function(){	        var flag=this.checked;	        if(flag){	            check_num=count;	        }else{	            check_num=0;	        }	        $('input[name="order_ids"]').each(function(){	            $(this).prop('checked',flag);	            var order_id=$(this).val();	            var key=$.inArray(order_id,order_arr);	            if(key>=0){	                if(!flag){	                    order_arr.splice(key, 1);	                }	            }else{	                if(flag){	                    order_arr.push(order_id);	                }	            }	        });	        order_id_list = order_arr.join(',');	        console.log('order_id_list----', order_id_list);	    });	    function doBill(){	        console.log('order_id_list1----', order_id_list);	    	if(order_id_list == ''){	    		layer.alert('请选择对账的订单');	    		return false;	    	}			layer.confirm('{pigcms{:L_("是否确认对账")}', function () {				$.post("{pigcms{:U('doBill')}",{'order_ids':order_id_list},function(data){	                if(data.error == 1){	                    layer.msg(data.info);	                }else{	                    layer.msg(data.info);	                    setTimeout(function(){	                    	location.reload()	                    },2000)	                }	            },'json')			}, function () {});	    		    }	</script>	<script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>